"use client"; // Required for Next.js 13+ with App Router

import { useState } from "react";

const CreateMeeting = () => {
  
  const [showForm, setShowForm] = useState(false);
  const [meetingDetails, setMeetingDetails] = useState({
    title: "",
    startTime: "",
    endTime: "",
    timeZone: "America/Los_Angeles",
    attendees: [],
  });
  const [meetLink, setMeetLink] = useState("");

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setMeetingDetails((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleAttendeesChange = (e) => {
    setMeetingDetails((prev) => ({
      ...prev,
      attendees: e.target.value.split(",").map((email) => email.trim()),
    }));
  };


  const createMeeting = async () => {
    try {
      const response = await fetch('http://localhost:5001/api/create-meeting', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(meetingDetails),
      });
      if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
      const data = await response.json();
      setMeetLink(data.meetLink);
    } catch (error) {
      console.error('Error creating meeting:', error);
    }
  };

  return (
    <div style={{ marginTop: "2rem" }}>
      {/* Toggle Button */}
      <button onClick={() => setShowForm(!showForm)}>
        {showForm ? "Hide Create Meeting Form" : "Show Create Meeting Form"}
      </button>

      {showForm && (
        <div>
          <h2>Create a Google Meet Meeting</h2>
          <form
            onSubmit={(e) => {
              e.preventDefault();
              createMeeting();
            }}
          >
            <div>
              <label>Title:</label>
              <input
                type="text"
                name="title"
                value={meetingDetails.title}
                onChange={handleInputChange}
                required
              />
            </div>
            <div>
              <label>Start Time:</label>
              <input
                type="datetime-local"
                name="startTime"
                value={meetingDetails.startTime}
                onChange={handleInputChange}
                required
              />
            </div>
            <div>
              <label>End Time:</label>
              <input
                type="datetime-local"
                name="endTime"
                value={meetingDetails.endTime}
                onChange={handleInputChange}
                required
              />
            </div>
            <div>
              <label>Time Zone:</label>
              <select
                name="timeZone"
                value={meetingDetails.timeZone}
                onChange={handleInputChange}
                required
              >
                <option value="America/Los_Angeles">Pacific Time (PT)</option>
                <option value="America/New_York">Eastern Time (ET)</option>
                <option value="UTC">UTC</option>
              </select>
            </div>
            <div>
              <label>Attendees (comma-separated emails):</label>
              <input
                type="text"
                name="attendees"
                value={meetingDetails.attendees.join(", ")}
                onChange={handleAttendeesChange}
                required
              />
            </div>
            <button type="submit">Create Meeting</button>
          </form>

          {/* Display Google Meet Link */}
          {meetLink && (
            <div style={{ marginTop: "1rem" }}>
              <h3>Google Meet Link:</h3>
              <a href={meetLink} target="_blank" rel="noopener noreferrer">
                {meetLink}
              </a>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default CreateMeeting;
